PromptEditor: FC<PromptEditorProps> = ({
  isEditMode = false,
  initialValues,
  isLoading = false,
  hasLoadError = false,
  isSaving = false,
  errors,
  descriptionMaxLength = DEFAULT_DESCRIPTION_MAX_LENGTH,
  contentMaxLength = DEFAULT_CONTENT_MAX_LENGTH,
  counterAnnounceThreshold = DEFAULT_ANNOUNCE_THRESHOLD,
  onSubmit,
  onCancel,
  onBack = onCancel,
  onRetry,
  labels,
  markdownEditorTheme,
  styles: editorStyles,
}) => {
  const { colors, typography } = editorStyles ?? {};
  const contentLabelClassName =
    typography?.contentLabelClassName ?? 'dial-tiny-semi-text';
  const helperTextClassName =
    typography?.helperTextClassName ?? 'dial-small-text';

  const [values, setValues] = useState<PromptEditorValues>({
    ...EMPTY_VALUES,
    ...initialValues,
  });
  const contentLabelId = useId();
  const contentEditorId = useId();
  const contentEditorCapRef = useAvailableHeightCap<HTMLDivElement>();

  /* Hosts that load asynchronously re-seed the form through `initialValues`. */
  useEffect(() => {
    setValues({ ...EMPTY_VALUES, ...initialValues });
  }, [initialValues]);

  const setField = useCallback(
    <K extends keyof PromptEditorValues>(
      field: K,
      value: PromptEditorValues[K],
    ) => {
      setValues((previous) => ({ ...previous, [field]: value }));
    },
    [],
  );

  const handleSubmit = useCallback(() => {
    if (isSaving) return;
    onSubmit(values);
  }, [isSaving, onSubmit, values]);

  const title = isEditMode
    ? (labels?.editTitle ?? 'Edit prompt')
    : (labels?.createTitle ?? 'Create prompt');

  const cssVars = buildCssVars({
    '--pe-content-error': colors?.contentErrorText,
  });

  const actions = (
    <>
      <NeutralButton
        label={labels?.cancelLabel ?? 'Cancel'}
        onClick={onCancel}
        disabled={isSaving}
      />
      <PrimaryButton
        label={labels?.saveLabel ?? 'Save'}
        iconBefore={isSaving ? <Spinner size={16} ariaLabel="" /> : undefined}
        onClick={handleSubmit}
        disabled={isSaving}
      />
    </>
  );

  if (isLoading) {
    return (
      <EditorLayout
        title={title}
        onBack={onBack}
        backAriaLabel={labels?.backButtonAriaLabel ?? 'Back to prompts'}
        actions={actions}
        isSaving={isSaving}
        labels={{ savingStatusLabel: labels?.savingStatusLabel }}
        leftContent={
          <div
            role="status"
            aria-label={labels?.loadingAriaLabel ?? 'Loading prompt'}
            className="flex flex-1 items-center justify-center p-8"
          >
            <Spinner />
          </div>
        }
      />
    );
  }

  if (hasLoadError) {
    return (
      <EditorLayout
        title={title}
        onBack={onBack}
        backAriaLabel={labels?.backButtonAriaLabel ?? 'Back to prompts'}
        actions={actions}
        isSaving={false}
        labels={{ savingStatusLabel: labels?.savingStatusLabel }}
        leftContent={
          <div role="alert" className="flex flex-col items-start gap-3 p-8">
            <p className={mergeClasses('m-0', helperTextClassName)}>
              {labels?.loadErrorMessage ??
                "Couldn't load this prompt. Please try again."}
            </p>
            {onRetry != null && (
              <NeutralButton
                label={labels?.retryLabel ?? 'Retry'}
                onClick={onRetry}
              />
            )}
          </div>
        }
      />
    );
  }

  const descriptionRemaining = getRemainingCharacters(
    values.description,
    descriptionMaxLength,
    counterAnnounceThreshold,
  );
  const contentRemaining = getRemainingCharacters(
    values.content,
    contentMaxLength,
    counterAnnounceThreshold,
  );
  const buildCounterMessage = (count: number) =>
    labels?.charactersRemaining?.(count) ?? `${count} characters remaining`;

  return (
    <EditorLayout
      title={title}
      onBack={onBack}
      backAriaLabel={labels?.backButtonAriaLabel ?? 'Back to prompts'}
      actions={actions}
      isSaving={isSaving}
      labels={{ savingStatusLabel: labels?.savingStatusLabel }}
      leftContent={
        <div
          className={mergeClasses(
            'mx-auto flex w-full max-w-[1180px] flex-1 flex-col gap-5 px-4 py-6 desktop:px-8',
            PROMPT_EDITOR_CLASS.form,
          )}
          style={cssVars}
        >
          <Input
            id="prompt-name"
            value={values.name}
            labelProps={{ label: labels?.nameLabel ?? 'Name', required: true }}
            placeholder={labels?.namePlaceholder ?? 'Prompt name'}
            invalid={errors?.name != null}
            error={errors?.name}
            onChange={(value) => setField('name', value ?? '')}
          />

          <Textarea
            id="prompt-description"
            value={values.description}
            labelProps={{ label: labels?.descriptionLabel ?? 'Description' }}
            placeholder={
              labels?.descriptionPlaceholder ?? 'What this prompt is for'
            }
            invalid={errors?.description != null}
            error={errors?.description}
            onChange={(value) => setField('description', value)}
          />

          <div
            role="group"
            aria-labelledby={contentLabelId}
            className="flex flex-1 flex-col gap-2"
          >
            {/*
             * htmlFor is what names the editor's textarea; without it the
             * label is only visible text sitting above an unnamed control.
             */}
            <Label
              id={contentLabelId}
              htmlFor={contentEditorId}
              label={labels?.contentLabel ?? 'Instructions'}
              required
              className={contentLabelClassName}
            />
            <div
              ref={contentEditorCapRef}
              className={mergeClasses(
                MARKDOWN_EDITOR_MAX_HEIGHT_CLASS_NAME,
                MARKDOWN_EDITOR_PREVIEW_LIST_CLASS_NAME,
              )}
            >
              <Suspense
                fallback={
                  <Spinner
                    ariaLabel={
                      labels?.contentLoadingAriaLabel ?? 'Loading prompt editor'
                    }
                  />
                }
              >
                <MarkdownEditor
                  id={contentEditorId}
                  value={values.content}
                  onChange={(value) => setField('content', value)}
                  height={480}
                  placeholder={
                    labels?.contentPlaceholder ??
                    'Write the prompt instructions'
                  }
                  theme={markdownEditorTheme}
                />
              </Suspense>
            </div>
            {errors?.content != null && (
              <p
                className={mergeClasses(
                  helperTextClassName,
                  styles.contentError,
                )}
              >
                {errors.content}
              </p>
            )}
          </div>

          <span role="status" aria-live="polite" className="sr-only">
            {descriptionRemaining != null &&
              buildCounterMessage(descriptionRemaining)}
            {contentRemaining != null && buildCounterMessage(contentRemaining)}
          </span>
        </div>
      }
    />
  );
}

PromptFolderField: FC<PromptFolderFieldProps> = ({
  value,
  folders,
  error,
  nameError,
  actions,
  disabled = false,
  labels,
  helperTextClassName = 'dial-small-text',
  onChange,
}) => {
  const [mode, setMode] = useState<FolderFormMode | null>(null);
  const [folderName, setFolderName] = useState('');
  const [validationError, setValidationError] = useState<string>();
  const [isPending, setIsPending] = useState(false);

  const isRootSelected = value === ROOT_FOLDER_ID;
  const rootOptionLabel = labels?.folderRootOption ?? 'Root';
  const emptyStateLabel = labels?.folderEmptyState ?? 'No folders yet';

  const options = useMemo(
    () => [
      { value: ROOT_OPTION_VALUE, label: rootOptionLabel },
      ...folders.map((folder) => ({ value: folder.id, label: folder.id })),
    ],
    [folders, rootOptionLabel],
  );

  const closeForm = useCallback(() => {
    setMode(null);
    setFolderName('');
    setValidationError(undefined);
  }, []);

  const handleSubmitName = useCallback(async () => {
    if (isPending || actions == null) return;

    const trimmed = folderName.trim();
    const message = actions.onValidateFolderName?.(trimmed);
    if (message != null) {
      setValidationError(message);
      return;
    }
    setValidationError(undefined);
    setIsPending(true);
    try {
      if (mode === FolderFormMode.Create) {
        const created = await actions.onCreateFolder(
          trimmed,
          isRootSelected ? undefined : value,
        );
        if (typeof created === 'string') onChange(created);
      } else {
        const renamed = await actions.onRenameFolder(value, trimmed);
        if (typeof renamed === 'string') onChange(renamed);
      }
      closeForm();
    } catch {
      /*
       * The host reports the failure through `nameError` (a conflict) or its
       * own notification surface; the sub-form stays open with the entered
       * name so it can be corrected.
       */
    } finally {
      setIsPending(false);
    }
  }, [
    isPending,
    actions,
    folderName,
    mode,
    isRootSelected,
    value,
    onChange,
    closeForm,
  ]);

  const handleConfirmDelete = useCallback(async () => {
    if (isPending || actions == null) return;
    setIsPending(true);
    try {
      await actions.onDeleteFolder(value);
      /*
       * The selected folder no longer exists, so fall back to root before the
       * next save targets a path that is gone.
       */
      onChange(ROOT_FOLDER_ID);
      closeForm();
    } catch {
      /* Reported by the host; leave the confirmation open. */
    } finally {
      setIsPending(false);
    }
  }, [isPending, actions, value, onChange, closeForm]);

  const openCreate = useCallback(() => {
    setFolderName('');
    setValidationError(undefined);
    setMode(FolderFormMode.Create);
  }, []);

  const openRename = useCallback(() => {
    setFolderName(lastSegment(value));
    setValidationError(undefined);
    setMode(FolderFormMode.Rename);
  }, [value]);

  const openDelete = useCallback(() => {
    setValidationError(undefined);
    setMode(FolderFormMode.ConfirmDelete);
  }, []);

  const handleSelect = useCallback(
    (next: string | string[] | null) => {
      const selected = Array.isArray(next) ? next[0] : next;
      if (selected == null) return;
      onChange(selected === ROOT_OPTION_VALUE ? ROOT_FOLDER_ID : selected);
    },
    [onChange],
  );

  const isNameFormOpen =
    mode === FolderFormMode.Create || mode === FolderFormMode.Rename;
  const nameFieldError = validationError ?? nameError;

  return (
    <div
      className={mergeClasses(
        'flex flex-col gap-2',
        PROMPT_EDITOR_CLASS.folderField,
      )}
    >
      <div className="flex items-end gap-2">
        <Select
          id="prompt-folder"
          className="flex-1"
          options={options}
          value={isRootSelected ? ROOT_OPTION_VALUE : value}
          labelProps={{ label: labels?.folderLabel ?? 'Folder' }}
          invalid={error != null}
          disabled={disabled}
          error={error}
          emptyStateTitle={emptyStateLabel}
          onChange={handleSelect}
        />
        {actions != null && !disabled && (
          <>
            <GhostIconButton
              icon={
                <IconFolderPlus
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              aria-label={labels?.folderCreateLabel ?? 'Create folder'}
              onClick={openCreate}
            />
            <GhostIconButton
              icon={
                <IconPencil
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              aria-label={labels?.folderRenameLabel ?? 'Rename folder'}
              disabled={isRootSelected}
              onClick={openRename}
            />
            <GhostIconButton
              icon={
                <IconTrashX
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              aria-label={labels?.folderDeleteLabel ?? 'Delete folder'}
              disabled={isRootSelected}
              onClick={openDelete}
            />
          </>
        )}
      </div>

      {folders.length === 0 && mode == null && (
        <p className={mergeClasses('m-0', helperTextClassName)}>
          {emptyStateLabel}
        </p>
      )}

      {/*
       * The sub-form repeats the outer form's Save/Cancel labels, so it is a
       * named region — otherwise both pairs are indistinguishable to a screen
       * reader walking the page's controls.
       */}
      {isNameFormOpen && (
        <div
          role="group"
          aria-label={
            mode === FolderFormMode.Create
              ? (labels?.folderCreateLabel ?? 'Create folder')
              : (labels?.folderRenameLabel ?? 'Rename folder')
          }
          className="flex items-end gap-2"
        >
          <Input
            id="prompt-folder-name"
            className="flex-1"
            value={folderName}
            autoFocus
            labelProps={{
              label: labels?.folderNameLabel ?? 'Folder name',
              required: true,
            }}
            invalid={nameFieldError != null}
            error={nameFieldError}
            onChange={(next) => setFolderName(next ?? '')}
          />
          <NeutralButton
            size={ElementSize.Standard}
            label={labels?.saveLabel ?? 'Save'}
            disabled={isPending}
            onClick={handleSubmitName}
          />
          <NeutralButton
            size={ElementSize.Standard}
            label={labels?.cancelLabel ?? 'Cancel'}
            disabled={isPending}
            onClick={closeForm}
          />
        </div>
      )}

      {mode === FolderFormMode.ConfirmDelete && (
        <div
          role="alertdialog"
          aria-label={labels?.folderDeleteConfirmTitle ?? 'Delete folder'}
        >
          <p className={mergeClasses('m-0 mb-2', helperTextClassName)}>
            {labels?.folderDeleteConfirmMessage?.(value) ??
              `Delete "${value}" and every prompt inside it?`}
          </p>
          <div className="flex gap-2">
            <NeutralButton
              size={ElementSize.Standard}
              label={labels?.folderDeleteLabel ?? 'Delete folder'}
              autoFocus
              disabled={isPending}
              onClick={handleConfirmDelete}
            />
            <NeutralButton
              size={ElementSize.Standard}
              label={labels?.cancelLabel ?? 'Cancel'}
              disabled={isPending}
              onClick={closeForm}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export interface PromptEditorErrors {
  /** Message shown under the name field. */
  name?: string;
  /** Message shown under the description field. */
  description?: string;
  /** Message shown under the content field. */
  content?: string;
}

export interface PromptEditorColors {
  /** Prompt validation error text. Fallback: `--text-error`. */
  contentErrorText?: string;
}

export interface PromptEditorFolder {
  /** Folder path, used as the option's value. The empty string is never listed — the root option is synthesised. */
  id: string;
  /** Display name shown in the picker. */
  name: string;
}

export interface PromptEditorLabels {
  /** Heading shown in create mode. Defaults to `'Create prompt'`. */
  createTitle?: string;
  /** Heading shown in edit mode. Defaults to `'Edit prompt'`. */
  editTitle?: string;
  /** Accessible label of the header back button. Defaults to `'Back to prompts'`. */
  backButtonAriaLabel?: string;
  /** Name field label. Defaults to `'Name'`. */
  nameLabel?: string;
  /** Name field placeholder. Defaults to `'Prompt name'`. */
  namePlaceholder?: string;
  /** Description field label. Defaults to `'Description'`. */
  descriptionLabel?: string;
  /** Description field placeholder. Defaults to `'What this prompt is for'`. */
  descriptionPlaceholder?: string;
  /** Content field label. Defaults to `'Instructions'`. */
  contentLabel?: string;
  /** Content field placeholder. Defaults to `'Write the prompt instructions'`. */
  contentPlaceholder?: string;
  /** Folder picker label, used by the standalone `PromptFolderField`. Defaults to `'Folder'`. */
  folderLabel?: string;
  /** Label of the root option in the folder picker. Defaults to `'Root'`. */
  folderRootOption?: string;
  /** Text shown when there are no folders yet. Defaults to `'No folders yet'`. */
  folderEmptyState?: string;
  /** Accessible label of the create-folder button. Defaults to `'Create folder'`. */
  folderCreateLabel?: string;
  /** Accessible label of the rename-folder button. Defaults to `'Rename folder'`. */
  folderRenameLabel?: string;
  /** Accessible label of the delete-folder button. Defaults to `'Delete folder'`. */
  folderDeleteLabel?: string;
  /** Label of the folder-name field in the create/rename sub-form. Defaults to `'Folder name'`. */
  folderNameLabel?: string;
  /** Title of the delete-folder confirmation. Defaults to `'Delete folder'`. */
  folderDeleteConfirmTitle?: string;
  /** Builds the delete-folder confirmation message. Defaults to a sentence naming the folder. */
  folderDeleteConfirmMessage?: (folderId: string) => string;
  /** Save button label. Defaults to `'Save'`. */
  saveLabel?: string;
  /** Cancel button label. Defaults to `'Cancel'`. */
  cancelLabel?: string;
  /** Retry button label shown in the load-error state. Defaults to `'Retry'`. */
  retryLabel?: string;
  /** Message shown when the prompt could not be loaded. Defaults to `"Couldn't load this prompt. Please try again."`. */
  loadErrorMessage?: string;
  /** Status announced while a save is in flight. Defaults to `'Saving'`. */
  savingStatusLabel?: string;
  /** Accessible label of the loading spinner. Defaults to `'Loading prompt'`. */
  loadingAriaLabel?: string;
  /** Accessible label of the markdown editor loading spinner. Defaults to `'Loading prompt editor'`. */
  contentLoadingAriaLabel?: string;
  /** Builds the characters-remaining announcement. Defaults to `` `${count} characters remaining` ``. */
  charactersRemaining?: (count: number) => string;
}

export interface PromptEditorProps {
  /** Whether the form edits an existing prompt (changes the heading only). Defaults to `false`. */
  isEditMode?: boolean;
  /**
   * Values to seed the fields with. Changing this object's identity re-seeds
   * the form, so hosts that load asynchronously should memoise it and only
   * produce a new object once the data has arrived.
   */
  initialValues?: Partial<PromptEditorValues>;
  /** Whether the prompt being edited is still loading. Defaults to `false`. */
  isLoading?: boolean;
  /** Whether loading the prompt failed; renders an error state with a retry instead of the form. Defaults to `false`. */
  hasLoadError?: boolean;
  /** Whether a save is in flight; disables submission. Defaults to `false`. */
  isSaving?: boolean;
  /** Inline validation messages to render under the fields. */
  errors?: PromptEditorErrors;
  /** Maximum description length used for the characters-remaining announcement. Defaults to `2000`. */
  descriptionMaxLength?: number;
  /** Maximum content length used for the characters-remaining announcement. Defaults to `50000`. */
  contentMaxLength?: number;
  /** How close to a limit the announcement starts, in characters. Defaults to `10`. */
  counterAnnounceThreshold?: number;
  /** Called with the current values when the form is submitted. */
  onSubmit: (values: PromptEditorValues) => void;
  /** Called when the form is dismissed without saving. */
  onCancel: () => void;
  /** Called when the header back button is activated. Defaults to `onCancel`. */
  onBack?: () => void;
  /** Called when the retry button in the load-error state is activated. */
  onRetry?: () => void;
  /** Text overrides. */
  labels?: PromptEditorLabels;
  /** Theme applied to the prompt markdown editor. Defaults to the editor's own default (`EditorThemes.light`). */
  markdownEditorTheme?: EditorThemes;
  /** Style overrides. */
  styles?: PromptEditorStyles;
}

export interface PromptEditorStyles {
  /** Color overrides applied as CSS custom properties. */
  colors?: PromptEditorColors;
  /** Typography class overrides. */
  typography?: PromptEditorTypography;
}

export interface PromptEditorTypography {
  /** Class applied to the prompt editor label. Defaults to `'dial-tiny-semi-text'`. */
  contentLabelClassName?: string;
  /** Class applied to helper, error, and confirmation text. Defaults to `'dial-small-text'`. */
  helperTextClassName?: string;
}

export interface PromptEditorValues {
  /** Prompt name. */
  name: string;
  /** Optional short description. */
  description: string;
  /** The prompt body. */
  content: string;
}

export interface PromptFolderActions {
  /** Creates a folder; resolve with its new path so the picker can select it. `parentId` is absent for a root-level folder. */
  onCreateFolder: (name: string, parentId?: string) => Promise<string | void>;
  /** Renames a folder; resolve with its new path so the picker can follow it. */
  onRenameFolder: (folderId: string, name: string) => Promise<string | void>;
  /** Deletes a folder and everything under it. */
  onDeleteFolder: (folderId: string) => Promise<void>;
  /** Validates a folder name before any mutation is dispatched; return a message to block it. */
  onValidateFolderName?: (name: string) => string | undefined;
}

export interface PromptFolderFieldProps {
  /** Currently selected folder path. The empty string means the root folder. */
  value: string;
  /** Folders offered by the picker, excluding the root. */
  folders: PromptEditorFolder[];
  /** Message shown under the picker itself. */
  error?: string;
  /** Message shown under the folder-name field of the create/rename sub-form. */
  nameError?: string;
  /** Folder mutations. Omit to render the picker without create/rename/delete controls. */
  actions?: PromptFolderActions;
  /** Whether the selected folder is read-only. */
  disabled?: boolean;
  /** Text overrides, shared with `PromptEditor`. */
  labels?: PromptEditorLabels;
  /** Class applied to helper and confirmation text. Defaults to `'dial-small-text'`. */
  helperTextClassName?: string;
  /** Called with the newly selected folder path (the empty string for root). */
  onChange: (folderId: string) => void;
}

export enum FolderFormMode {
  /** Creating a new folder under the selected one. */
  Create = 'create',
  /** Renaming the selected folder. */
  Rename = 'rename',
  /** Confirming deletion of the selected folder. */
  ConfirmDelete = 'confirmDelete',
}

PROMPT_EDITOR_CLASS = {
  /** The editor's scrolling form column, inside the shared editor layout. */
  form: 'dial-prompt-editor-form',
  /** The folder picker row rendered by `PromptFolderField`. */
  folderField: 'dial-prompt-editor-folder-field',
} as const

